// Embedded media and styles for the standalone HTML download.
window.SNAPSHOT_ASSETS = {"css":":root{--background-pink:#faeef0;--darker-pink:#f2dce1;--accent-pink:#a83f59;--text:#4c2933;--muted:#80646d;--cream:#fffaf3;--shadow:0 18px 55px #6b293314;--radius:24px;--speed:300ms;--ease:cubic-bezier(.22,1,.36,1)}\n*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:85px}body{margin:0;background:var(--background-pink);color:var(--text);font:16px/1.7 'Segoe UI',sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}a{color:inherit}button:focus-visible,a:focus-visible,summary:focus-visible,.carousel:focus-visible{outline:3px solid #8b3650;outline-offset:6px}button:disabled{cursor:default}h1,h2,h3,p{margin-top:0}h1,h2,h3{font-family:Georgia,'Times New Roman',serif;font-weight:400;line-height:1.15;letter-spacing:-1.8px}h1{font-size:clamp(46px,5.6vw,76px);margin-bottom:24px}h2{font-size:clamp(33px,4vw,49px);margin-bottom:18px}h2 span{font-size:.6em}h3{font-size:29px}em{color:var(--accent-pink);font-weight:400}button,a{touch-action:manipulation}.section{padding:100px 24px;text-align:center;position:relative}.section-heading{max-width:680px;margin:0 auto 42px}.section-heading p,.hero-description{color:var(--muted)}.eyebrow{display:block;font-size:10px;letter-spacing:2.7px;font-weight:650;margin-bottom:22px}.site-header{height:86px;display:flex;align-items:center;justify-content:space-between;max-width:1300px;margin:auto;padding:0 5%;gap:15px}.wordmark{text-decoration:none;font-family:Georgia,serif;font-size:23px}.wordmark span{color:var(--accent-pink);margin-left:7px}.music{border:1px solid #cba5af;background:#fff8f980;color:var(--text);border-radius:25px;padding:9px 16px;font-size:12px;min-height:44px}.hero{padding-top:26px;min-height:calc(100svh - 86px)}.hero>.eyebrow{margin-bottom:14px}.bear-art{width:220px;max-width:70%;margin:0 auto 23px;position:relative}.bear-art svg{display:block;width:100%}.art-note{font:italic 12px Georgia,serif;color:var(--muted)}.heading-emoji{font-size:.48em}.hero-description{font-size:16px;line-height:1.9;margin-bottom:28px}.button{border-radius:30px;min-height:50px;padding:13px 26px;display:inline-flex;justify-content:center;align-items:center;gap:15px;text-decoration:none;font-size:14px;font-weight:600;border:1px solid transparent;transition:transform var(--speed) var(--ease),box-shadow var(--speed),background var(--speed)}.primary{background:var(--accent-pink);color:#fff7f7;box-shadow:0 6px 18px #a83f5926}.button:hover{transform:translateY(-3px);box-shadow:0 10px 24px #a83f5930}.button:active{transform:scale(.97)}.secondary{background:transparent;border-color:#cda7b0;color:var(--text)}.whats{font-size:12px;color:var(--muted);margin:20px auto 0;max-width:420px}.whats summary{cursor:pointer;list-style:none}.whats p{padding:14px 8px 0}.scroll-note{display:block;font-size:9px;letter-spacing:2px;text-decoration:none;margin-top:44px;color:var(--muted)}.scroll-note span{display:block;font-size:21px;margin-top:6px}.memories{background:#f5e3e7}.carousel{max-width:460px;margin:auto;touch-action:pan-y;user-select:none;cursor:grab;padding:12px 20px 18px}.carousel:active{cursor:grabbing}.memory-cards{position:relative;aspect-ratio:4/4.8}.memory-card{position:absolute;inset:0;padding:15px 15px 23px;background:var(--cream);border:1px solid #ebd9d9;border-radius:7px;box-shadow:var(--shadow);transition:transform .5s var(--ease),opacity .4s}.memory-card.is-active{transform:rotate(-2deg);z-index:3}.memory-card.is-next{transform:rotate(5deg) translate(7px,3px);z-index:2}.memory-card.is-hidden{opacity:0;transform:rotate(-6deg) scale(.97);pointer-events:none}.photo{height:78%;position:relative;overflow:hidden;background:#efdbd6}.photo img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}.photo img[hidden]{display:none}.photo-fallback{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at 30% 20%,#fff6e7,transparent 65%),linear-gradient(135deg,#e6c9bd,#dba6ae);color:#805465}.photo-fallback .motif{font-family:Georgia,serif;font-size:70px;line-height:1.2}.photo-fallback small{font:italic 15px Georgia,serif;margin-top:14px}.memory-card:nth-child(2n) .photo-fallback{background:linear-gradient(130deg,#e8ded4,#c4c6b5)}.memory-card:nth-child(3n) .photo-fallback{background:linear-gradient(130deg,#eee0ce,#d7b69b)}.memory-caption{font:italic 19px Georgia,serif;margin:20px 0 5px}.memory-number{font-size:9px;letter-spacing:2px;color:var(--muted)}.carousel-controls{display:flex;align-items:center;justify-content:center;gap:27px;margin-top:18px}.circle-button{width:44px;height:44px;border:1px solid #cba5af;background:transparent;border-radius:50%;color:var(--text);transition:background .2s}.circle-button:hover{background:var(--cream)}#memory-count{font-size:11px;letter-spacing:3px}.hint{font-size:12px;color:var(--muted);margin:14px 0 26px}.text-link{display:inline-block;font-size:12px;text-underline-offset:6px;margin-top:28px;color:var(--accent-pink)}.letter-section{background:#faf1ed}.letter{max-width:660px;margin:auto;padding:42px 58px;text-align:left;background:var(--cream);box-shadow:var(--shadow);border:1px solid #eaded3;position:relative;transform:rotate(-.7deg)}.letter:before{content:'';position:absolute;width:105px;height:28px;background:#ead9cbbb;top:-13px;left:calc(50% - 52px);transform:rotate(-4deg)}.letter-top{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:2.5px;color:var(--muted);border-bottom:1px solid #e8dcd1;margin-bottom:30px;padding-bottom:15px}.letter-top span:last-child{font-size:29px;color:var(--accent-pink)}.letter h3,.signature{font-family:'Segoe Print','Bradley Hand',cursive;color:var(--accent-pink);letter-spacing:-.5px}.letter p{font-size:15px;line-height:1.9;margin-bottom:19px}.letter .signature{font-size:23px;margin:30px 0 0}.meter-card{max-width:520px;margin:auto;background:#fff8f9;padding:35px;border:1px solid #e9ccd4;border-radius:var(--radius);box-shadow:var(--shadow)}.mini-bear{font-size:45px;display:block;margin-bottom:28px}.meter-label{display:flex;justify-content:space-between;font-size:10px;letter-spacing:2px;margin-bottom:10px;font-weight:600}.meter-track{height:13px;border-radius:10px;background:#eddce1;overflow:hidden}#meter-fill{height:100%;background:linear-gradient(90deg,#d793a4,#a83f59);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}#meter-message{font:italic 18px Georgia,serif;min-height:45px;margin:25px 0 0}.heart-button{display:block;margin:8px auto 20px;border:0;background:transparent;color:var(--accent-pink);font-size:85px;line-height:1;padding:8px 25px;filter:drop-shadow(0 8px 8px #a83f5920);transition:transform .2s}.heart-button:hover{transform:scale(1.08)}.heart-button.pulse{animation:pulse .45s}.tap-note{font-size:9px;letter-spacing:1.3px;margin-bottom:15px}.small-note{font-size:12px;color:var(--muted);margin:0}.coupons-section{background:#f5e3e7}.coupons-grid{max-width:1040px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.coupon{text-align:left;background:var(--cream);border:1px solid #e6ccd1;border-radius:14px;padding:27px 25px 20px;box-shadow:0 8px 24px #6b293309;display:flex;flex-direction:column;transition:transform .3s}.coupon:hover{transform:translateY(-4px)}.coupon-icon{font-size:32px;margin-bottom:18px}.coupon h3{font-family:'Segoe UI',sans-serif;font-size:11px;letter-spacing:2px;font-weight:650;margin-bottom:12px}.coupon p{font-size:13px;color:var(--muted);line-height:1.8;flex:1;white-space:pre-line}.coupon-bottom{border-top:1px dashed #d8b8bf;padding-top:17px;display:flex;align-items:center;justify-content:space-between;gap:8px}.coupon-bottom small{font-size:9px;letter-spacing:1px;color:var(--muted)}.redeem{border:0;background:transparent;color:var(--accent-pink);font-size:10px;letter-spacing:1px;font-weight:700;min-height:44px;padding:5px}.coupon.redeemed{background:#f9f2e9}.final-section{padding-top:110px}.final-copy{max-width:510px;margin:30px auto;color:var(--muted);font-size:15px}.final-copy p{margin-bottom:18px}.big-sorry{font:italic 32px Georgia,serif;color:var(--accent-pink);margin-top:35px}.no-ego{font-size:12px;color:var(--muted)}.question-card{max-width:570px;margin:45px auto 0;border-top:1px solid #e0c3cc;padding:35px 0 0}.question-card h3{font-size:27px;letter-spacing:-.7px}.answers{display:flex;justify-content:center;gap:14px;flex-wrap:wrap}.answers .button{min-width:130px}.answer:empty{display:none}.answer{margin-top:28px;padding:22px;background:var(--cream);border-radius:16px;white-space:pre-line;font-size:15px}.answer strong{font:24px Georgia,serif;display:block;margin-bottom:12px}footer{border-top:1px solid #e8cfd6;text-align:center;padding:35px 24px;font-size:11px;color:var(--muted)}footer>span{color:var(--accent-pink);font-size:17px}footer small{font-size:10px}.intro{position:fixed;inset:0;background:#191519;color:#f7eaec;z-index:100;display:flex;align-items:center;justify-content:center;text-align:center;padding:25px;transition:opacity .7s}.intro[hidden]{display:none}.intro-copy{max-width:650px}.intro .eyebrow{color:#bd8d9b;animation:fadeIn .8s both}.intro p{font:clamp(23px,4vw,38px)/1.5 Georgia,serif;opacity:0;animation:fadeIn 1s forwards}.intro p:nth-of-type(2){animation-delay:1.1s}.intro p:nth-of-type(3){animation-delay:2.3s}.intro-heart{display:block;font-size:30px;color:#c58b9d;animation:fadeIn 1s 3s both}.intro-skip{position:absolute;bottom:45px;border:1px solid #735663;color:#f7eaec;background:transparent;border-radius:25px;padding:12px 24px}.intro.is-leaving{opacity:0;pointer-events:none}.intro-open{overflow:hidden}#heart-layer{position:fixed;inset:0;overflow:hidden;pointer-events:none;z-index:101}.floating-heart{position:absolute;bottom:-30px;color:#bb647d;animation:floatUp var(--duration,7s) linear forwards;opacity:0}.burst{bottom:auto;animation:burst 1.3s var(--ease) forwards}.confetti{width:7px;height:11px;background:var(--accent-pink);border-radius:2px}.reveal{transition:opacity .7s,translate .7s}.reveal.pending{opacity:0;translate:0 20px}.skip-link{position:fixed;top:-100px;left:12px;background:var(--cream);padding:10px;z-index:200}.skip-link:focus{top:10px}.noscript{padding:20px;text-align:center}@keyframes fadeIn{to{opacity:1}}@keyframes pulse{50%{transform:scale(1.25)}}@keyframes floatUp{15%{opacity:.3}85%{opacity:.2}to{transform:translate(35px,-110vh) rotate(25deg);opacity:0}}@keyframes burst{0%{opacity:.8}to{transform:translate(var(--x),var(--y)) rotate(120deg);opacity:0}}\n@media(min-width:1000px){.hero:before,.hero:after{content:'♡';position:absolute;color:#d9aab7;font:100px Georgia,serif;top:36%;left:17%;transform:rotate(-18deg)}.hero:after{left:auto;right:17%;top:52%;font-size:60px;transform:rotate(16deg)}}@media(max-width:700px){.section{padding:75px 22px}.site-header{padding:0 22px;height:76px}.wordmark{font-size:20px}.music{padding:8px 12px;font-size:10px}.hero{padding-top:25px;min-height:calc(100svh - 76px)}.bear-art{width:190px}.hero h1{font-size:48px}.coupons-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.coupon{padding:22px 18px 14px}.letter{padding:30px 25px}.letter p{font-size:14px}.letter h3{font-size:25px}.meter-card{padding:28px 22px}.section-heading{margin-bottom:30px}.eyebrow{font-size:9px;letter-spacing:2px}.carousel{max-width:350px;padding:10px 14px}.memory-caption{font-size:17px}.final-copy{font-size:14px}.intro p{font-size:26px}}\n@media(max-width:450px){.coupons-grid{grid-template-columns:1fr}.coupon{padding:24px;display:grid;grid-template-columns:44px 1fr;column-gap:15px}.coupon-icon{grid-row:1/3;margin:0}.coupon h3{margin:3px 0 9px}.coupon p{grid-column:2;margin-bottom:20px}.coupon-bottom{grid-column:1/-1}.hero h1{font-size:44px}.section h2{font-size:34px}.section-heading p{font-size:14px}.scroll-note{font-size:8px}.memory-caption{margin-top:15px}.question-card h3{font-size:25px}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}.intro p{opacity:1}.floating-heart{display:none}.reveal.pending{opacity:1;translate:none}}\r\n.photo-fallback[hidden]{display:none}\r\n\n/* Each poem has its own opening and closing quotation marks. */\n.poem + .poem{border-top:1px solid #e8dcd1;margin-top:30px;padding-top:26px}\n.poem-quote{display:block;color:var(--accent-pink);font:44px/1 Georgia,serif;margin-bottom:8px}\n.poem-quote-close{text-align:right;margin:0}\n\n#reset-meter[hidden]{display:none}\n#reset-meter{margin:0 auto 22px}\n\n/* Keep the whole photo visible, including both faces. */\n.memory-cards{aspect-ratio:4/5.2}\n.photo{height:auto;aspect-ratio:1}\n.photo img{object-fit:contain}\n.memory-caption{line-height:1.4}\n","photos":{"photo1.jpg":"data:image/jpeg;base64,","photo2.jpg":"data:image/jpeg;base64,","photo3.jpg":"data:image/jpeg;base64,","photo4.jpg":"data:image/jpeg;base64,","photo5.jpg":"data:image/jpeg;base64,"},"music":"data:audio/mpeg;base64,"};
